// Validate validates a config against the schema.
func (s *Schema) Validate(cfg *Config) []ValidationError {
	var errs []ValidationError

	// Convert config to map for easier validation
	data, err := configToMap(cfg)
	if err != nil {
		return []ValidationError{{Message: "failed to convert config"}}
	}

	// Validate each field
	for path, fieldSchema := range s.Fields {
		value := getNestedValue(data, path)

		// Check required
		if fieldSchema.Required && value == nil {
			errs = append(errs, ValidationError{
				Field:   path,
				Message: "required field is missing",
			})
			continue
		}

		if value == nil {
			continue
		}

		// Type validation
		if err := s.validateType(path, value, fieldSchema); err != nil {
			errs = append(errs, *err)
			continue
		}

		// Range validation
		if err := s.validateRange(path, value, fieldSchema); err != nil {
			errs = append(errs, *err)
		}

		// Enum validation
		if err := s.validateEnum(path, value, fieldSchema); err != nil {
			errs = append(errs, *err)
		}

		// Pattern validation
		if err := s.validatePattern(path, value, fieldSchema); err != nil {
			errs = append(errs, *err)
		}

		// Length validation
		if err := s.validateLength(path, value, fieldSchema); err != nil {
			errs = append(errs, *err)
		}
	}

	return errs
}

// validateType checks if the value matches the expected type.
func (s *Schema) validateType(path string, value any, fs FieldSchema) *ValidationError {
	valid := false

	switch fs.Type {
	case TypeString, TypeDuration, TypeSize:
		_, valid = value.(string)
	case TypeInt:
		switch value.(type) {
		case int, int64, float64:
			valid = true
		}
	case TypeFloat:
		switch value.(type) {
		case float64, float32, int:
			valid = true
		}
	case TypeBool:
		_, valid = value.(bool)
	case TypeArray:
		kind := reflect.TypeOf(value).Kind()
		valid = kind == reflect.Slice || kind == reflect.Array
	case TypeMap:
		kind := reflect.TypeOf(value).Kind()
		valid = kind == reflect.Map
	}

	if !valid {
		return &ValidationError{
			Field:   path,
			Message: fmt.Sprintf("expected %s type", fs.Type),
			Value:   value,
		}
	}
	return nil
}

// validateRange checks numeric range constraints.
func (s *Schema) validateRange(path string, value any, fs FieldSchema) *ValidationError {
	var num float64

	switch v := value.(type) {
	case int:
		num = float64(v)
	case int64:
		num = float64(v)
	case float64:
		num = v
	default:
		return nil
	}

	if fs.Min != nil && num < *fs.Min {
		return &ValidationError{
			Field:   path,
			Message: fmt.Sprintf("value must be >= %v", *fs.Min),
			Value:   value,
		}
	}

	if fs.Max != nil && num > *fs.Max {
		return &ValidationError{
			Field:   path,
			Message: fmt.Sprintf("value must be <= %v", *fs.Max),
			Value:   value,
		}
	}

	return nil
}

// validateEnum checks if value is in allowed enum values.
func (s *Schema) validateEnum(path string, value any, fs FieldSchema) *ValidationError {
	if len(fs.Enum) == 0 {
		return nil
	}

	str, ok := value.(string)
	if !ok {
		return nil
	}

	for _, allowed := range fs.Enum {
		if str == allowed {
			return nil
		}
	}

	return &ValidationError{
		Field:   path,
		Message: fmt.Sprintf("must be one of: %v", fs.Enum),
		Value:   value,
	}
}

// validatePattern checks regex pattern constraint.
func (s *Schema) validatePattern(path string, value any, fs FieldSchema) *ValidationError {
	if fs.Pattern == nil {
		return nil
	}

	str, ok := value.(string)
	if !ok {
		return nil
	}

	if !fs.Pattern.MatchString(str) {
		return &ValidationError{
			Field:   path,
			Message: fmt.Sprintf("must match pattern: %s", fs.Pattern.String()),
			Value:   value,
		}
	}

	return nil
}

// validateLength checks string/array length constraints.
func (s *Schema) validateLength(path string, value any, fs FieldSchema) *ValidationError {
	var length int

	switch v := value.(type) {
	case string:
		length = len(v)
	case []any:
		length = len(v)
	default:
		return nil
	}

	if fs.MinLen != nil && length < *fs.MinLen {
		return &ValidationError{
			Field:   path,
			Message: fmt.Sprintf("length must be >= %d", *fs.MinLen),
			Value:   value,
		}
	}

	if fs.MaxLen != nil && length > *fs.MaxLen {
		return &ValidationError{
			Field:   path,
			Message: fmt.Sprintf("length must be <= %d", *fs.MaxLen),
			Value:   value,
		}
	}

	return nil
}

// getNestedValue retrieves a value from a nested map using dot notation.
func getNestedValue(data map[string]any, path string) any {
	parts := strings.Split(path, ".")
	current := data

	for i, part := range parts {
		val, ok := current[part]
		if !ok {
			return nil
		}

		// If this is the last part, return the value
		if i == len(parts)-1 {
			return val
		}

		// Otherwise, descend into nested map
		next, ok := val.(map[string]any)
		if !ok {
			return nil
		}
		current = next
	}

	return nil
}

// GenerateSchemaDoc generates documentation from the schema.
func (s *Schema) GenerateSchemaDoc() string {
	var b strings.Builder

	b.WriteString("# Automergent Configuration Schema\n\n")

	// Group by prefix
	groups := make(map[string][]string)
	for path := range s.Fields {
		parts := strings.SplitN(path, ".", 2)
		group := "General"
		if len(parts) > 1 {
			group = strings.Title(parts[0])
		}
		groups[group] = append(groups[group], path)
	}

	for group, paths := range groups {
		b.WriteString(fmt.Sprintf("## %s\n\n", group))

		for _, path := range paths {
			fs := s.Fields[path]
			b.WriteString(fmt.Sprintf("### `%s`\n\n", path))

			if fs.Description != "" {
				b.WriteString(fmt.Sprintf("%s\n\n", fs.Description))
			}

			b.WriteString(fmt.Sprintf("- **Type**: %s\n", fs.Type))

			if fs.Default != nil {
				b.WriteString(fmt.Sprintf("- **Default**: `%v`\n", fs.Default))
			}

			if fs.Required {
				b.WriteString("- **Required**: yes\n")
			}

			if len(fs.Enum) > 0 {
				b.WriteString(fmt.Sprintf("- **Allowed values**: %v\n", fs.Enum))
			}

			if fs.Min != nil || fs.Max != nil {
				if fs.Min != nil && fs.Max != nil {
					b.WriteString(fmt.Sprintf("- **Range**: %v - %v\n", *fs.Min, *fs.Max))
				} else if fs.Min != nil {
					b.WriteString(fmt.Sprintf("- **Minimum**: %v\n", *fs.Min))
				} else {
					b.WriteString(fmt.Sprintf("- **Maximum**: %v\n", *fs.Max))
				}
			}

			if fs.Deprecated {
				b.WriteString("- **Deprecated**: yes\n")
			}

			if fs.Sensitive {
				b.WriteString("- **Sensitive**: yes (secret)\n")
			}

			b.WriteString("\n")
		}
	}

	return b.String()
}

// ValidateFile validates a config file without loading it.
func ValidateFile(path string) ([]ValidationError, error) {
	loader, err := NewLoader(&LoaderOptions{
		GlobalPath: path,
		Schema:     DefaultSchema(),
	})
	if err != nil {
		return nil, err
	}

	_, err = loader.Load()
	if err != nil {
		// Try to extract validation errors
		return []ValidationError{{Message: err.Error()}}, nil
	}

	return nil, nil
}

package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/fsnotify/fsnotify"
	"gopkg.in/yaml.v3"
)

// Layer represents a configuration layer priority.
type Layer int

const (
	// LayerDefaults is the lowest priority, built-in defaults.
	LayerDefaults Layer = iota
	// LayerGlobal is user's global config (~/.automergent/config.yaml).
	LayerGlobal
	// LayerProject is project-specific config (.automergent/config.yaml).
	LayerProject
	// LayerProfile is named profile configuration.
	LayerProfile
	// LayerEnv is environment variables (AUTOMERGENT_*).
	LayerEnv
	// LayerSession is temporary session overrides.
	LayerSession
	// LayerCLI is CLI flags (highest priority).
	LayerCLI
)

// String returns the layer name.
func (l Layer) String() string {
	switch l {
	case LayerDefaults:
		return "defaults"
	case LayerGlobal:
		return "global"
	case LayerProject:
		return "project"
	case LayerProfile:
		return "profile"
	case LayerEnv:
		return "env"
	case LayerSession:
		return "session"
	case LayerCLI:
		return "cli"
	default:
		return "unknown"
	}
}

// LayerSource tracks where a config value came from.
type LayerSource struct {
	Layer Layer
	File  string // File path if loaded from file
	Key   string // Original key name
}

// Loader handles multi-layer configuration loading and merging.
type Loader struct {
	mu sync.RWMutex

	// Configuration state
	config      *Config
	layers      map[Layer]map[string]any
	sources     map[string]LayerSource
	globalPath  string
	projectPath string
	profileName string

	// Hot reload
	watcher   *fsnotify.Watcher
	reloadCh  chan struct{}
	onReload  []func(*Config)
	stopWatch chan struct{}

	// Schema validation
	schema *Schema
}

// LoaderOptions configures the loader behavior.
type LoaderOptions struct {
	// GlobalPath overrides the default global config path.
	GlobalPath string
	// ProjectDir is the project directory to search for .automergent/config.yaml.
	ProjectDir string
	// Profile selects a named profile to load.
	Profile string
	// EnableHotReload enables watching config files for changes.
	EnableHotReload bool
	// Schema enables schema validation.
	Schema *Schema
}

// NewLoader creates a new configuration loader.
func NewLoader(opts *LoaderOptions) (*Loader, error) {
	if opts == nil {
		opts = &LoaderOptions{}
	}

	l := &Loader{
		layers:    make(map[Layer]map[string]any),
		sources:   make(map[string]LayerSource),
		reloadCh:  make(chan struct{}, 1),
		stopWatch: make(chan struct{}),
		schema:    opts.Schema,
	}

	// Determine global config path
	if opts.GlobalPath != "" {
		l.globalPath = opts.GlobalPath
	} else {
		home, err := os.UserHomeDir()
		if err != nil {
			return nil, fmt.Errorf("get home dir: %w", err)
		}
		l.globalPath = filepath.Join(home, ".automergent", "config.yaml")
	}

	// Determine project config path
	if opts.ProjectDir != "" {
		l.projectPath = filepath.Join(opts.ProjectDir, ".automergent", "config.yaml")
	} else if wd, err := os.Getwd(); err == nil {
		l.projectPath = findProjectConfig(wd)
	}

	l.profileName = opts.Profile

	// Initialize hot reload if enabled
	if opts.EnableHotReload {
		watcher, err := fsnotify.NewWatcher()
		if err != nil {
			return nil, fmt.Errorf("create watcher: %w", err)
		}
		l.watcher = watcher
		go l.watchLoop()
	}

	return l, nil
}

// findProjectConfig searches up the directory tree for .automergent/config.yaml.
func findProjectConfig(startDir string) string {
	dir := startDir
	for {
		configPath := filepath.Join(dir, ".automergent", "config.yaml")
		if _, err := os.Stat(configPath); err == nil {
			return configPath
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return ""
}

// Load performs the full configuration loading sequence.
func (l *Loader) Load() (*Config, error) {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Clear previous state
	l.layers = make(map[Layer]map[string]any)
	l.sources = make(map[string]LayerSource)

	// Load each layer in priority order
	if err := l.loadDefaults(); err != nil {
		return nil, fmt.Errorf("load defaults: %w", err)
	}

	if err := l.loadGlobal(); err != nil {
		return nil, fmt.Errorf("load global: %w", err)
	}

	if err := l.loadProject(); err != nil {
		return nil, fmt.Errorf("load project: %w", err)
	}

	if err := l.loadProfile(); err != nil {
		return nil, fmt.Errorf("load profile: %w", err)
	}

	if err := l.loadEnv(); err != nil {
		return nil, fmt.Errorf("load env: %w", err)
	}

	// Merge all layers
	cfg, err := l.merge()
	if err != nil {
		return nil, fmt.Errorf("merge config: %w", err)
	}

	// Validate against schema
	if l.schema != nil {
		if errs := l.schema.Validate(cfg); len(errs) > 0 {
			return nil, fmt.Errorf("schema validation: %v", errs)
		}
	}

	l.config = cfg
	return cfg, nil
}

// loadDefaults loads built-in defaults.
func (l *Loader) loadDefaults() error {
	defaults := Default()
	data, err := configToMap(defaults)
	if err != nil {
		return err
	}
	flat := flattenMap(data)
	l.layers[LayerDefaults] = flat
	for k := range flat {
		l.sources[k] = LayerSource{Layer: LayerDefaults, Key: k}
	}
	return nil
}

// loadGlobal loads the global config file.
func (l *Loader) loadGlobal() error {
	if l.globalPath == "" {
		return nil
	}

	data, err := l.loadFile(l.globalPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	flat := flattenMap(data)
	l.layers[LayerGlobal] = flat
	for k := range flat {
		l.sources[k] = LayerSource{Layer: LayerGlobal, File: l.globalPath, Key: k}
	}

	// Add to watcher
	if l.watcher != nil {
		_ = l.watcher.Add(l.globalPath)
	}

	return nil
}

// loadProject loads the project config file.
func (l *Loader) loadProject() error {
	if l.projectPath == "" {
		return nil
	}

	data, err := l.loadFile(l.projectPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	flat := flattenMap(data)
	l.layers[LayerProject] = flat
	for k := range flat {
		l.sources[k] = LayerSource{Layer: LayerProject, File: l.projectPath, Key: k}
	}

	// Add to watcher
	if l.watcher != nil {
		_ = l.watcher.Add(l.projectPath)
	}

	return nil
}

// loadProfile loads a named profile.
func (l *Loader) loadProfile() error {
	if l.profileName == "" {
		return nil
	}

	// Check global profiles directory
	home, err := os.UserHomeDir()
	if err != nil {
		return err
	}

	profilePath := filepath.Join(home, ".automergent", "profiles", l.profileName+".yaml")
	data, err := l.loadFile(profilePath)
	if err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("profile %q not found", l.profileName)
		}
		return err
	}

	flat := flattenMap(data)
	l.layers[LayerProfile] = flat
	for k := range flat {
		l.sources[k] = LayerSource{Layer: LayerProfile, File: profilePath, Key: k}
	}

	return nil
}

// loadEnv loads configuration from environment variables.
func (l *Loader) loadEnv() error {
	data := make(map[string]any)
	prefix := "AUTOMERGENT_"

	for _, env := range os.Environ() {
		if !strings.HasPrefix(env, prefix) {
			continue
		}

		parts := strings.SplitN(env, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.ToLower(strings.TrimPrefix(parts[0], prefix))
		key = strings.ReplaceAll(key, "_", ".")
		value := parts[1]

		// Try to parse as JSON for complex values
		var parsed any
		if err := json.Unmarshal([]byte(value), &parsed); err == nil {
			data[key] = parsed
		} else {
			// Handle common types
			data[key] = parseEnvValue(value)
		}

		l.sources[key] = LayerSource{Layer: LayerEnv, Key: parts[0]}
	}

	l.layers[LayerEnv] = data
	return nil
}

// parseEnvValue converts string env value to appropriate type.
func parseEnvValue(value string) any {
	// Boolean
	switch strings.ToLower(value) {
	case "true", "1", "yes", "on":
		return true
	case "false", "0", "no", "off":
		return false
	}

	// Try int
	var intVal int
	if _, err := fmt.Sscanf(value, "%d", &intVal); err == nil {
		return intVal
	}

	// Try float
	var floatVal float64
	if _, err := fmt.Sscanf(value, "%f", &floatVal); err == nil {
		return floatVal
	}

	return value
}

// SetSession sets session-level overrides (temporary).
func (l *Loader) SetSession(key string, value any) {
	l.mu.Lock()
	defer l.mu.Unlock()

	if l.layers[LayerSession] == nil {
		l.layers[LayerSession] = make(map[string]any)
	}
	l.layers[LayerSession][key] = value
	l.sources[key] = LayerSource{Layer: LayerSession, Key: key}
}

// ApplyCLIFlags applies CLI flags as the highest priority layer.
func (l *Loader) ApplyCLIFlags(flags *CLIFlags) {
	l.mu.Lock()
	defer l.mu.Unlock()

	data := make(map[string]any)

	if flags.Provider != "" {
		data["provider"] = flags.Provider
	}
	if flags.Model != "" {
		data["model"] = flags.Model
	}
	if flags.Mode != "" {
		data["mode"] = flags.Mode
	}
	if flags.Theme != "" {
		data["theme"] = flags.Theme
	}
	if flags.Keybindings != "" {
		data["keybindings"] = flags.Keybindings
	}
	if flags.Layout != "" {
		data["layout"] = flags.Layout
	}
	if flags.SessionDir != "" {
		data["sessionDir"] = flags.SessionDir
	}
	if flags.NoTUI {
		data["noTui"] = true
	}
	if flags.NoColor {
		data["noColor"] = true
	}
	if flags.Quiet {
		data["quiet"] = true
	}
	if flags.Verbose {
		data["verbose"] = true
	}
	if flags.NoAnimation {
		data["noAnimation"] = true
	}
	if flags.NoSandbox {
		data["security.sandbox"] = "off"
	}
	if flags.Sandbox != "" {
		data["security.sandbox"] = flags.Sandbox
	}

	l.layers[LayerCLI] = data
	for k := range data {
		l.sources[k] = LayerSource{Layer: LayerCLI, Key: k}
	}
}

// loadFile loads a YAML, JSON, or TOML file.
func (l *Loader) loadFile(path string) (map[string]any, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	ext := strings.ToLower(filepath.Ext(path))
	var data map[string]any

	switch ext {
	case ".yaml", ".yml":
		if err := yaml.Unmarshal(content, &data); err != nil {
			return nil, fmt.Errorf("parse yaml: %w", err)
		}
	case ".json":
		if err := json.Unmarshal(content, &data); err != nil {
			return nil, fmt.Errorf("parse json: %w", err)
		}
	case ".toml":
		// TOML support using simple parser (avoiding external dependency)
		data, err = parseTOML(content)
		if err != nil {
			return nil, fmt.Errorf("parse toml: %w", err)
		}
	default:
		// Try YAML by default
		if err := yaml.Unmarshal(content, &data); err != nil {
			return nil, fmt.Errorf("parse file: %w", err)
		}
	}

	return data, nil
}

// parseTOML provides basic TOML parsing for simple config files.
func parseTOML(content []byte) (map[string]any, error) {
	result := make(map[string]any)
	lines := strings.Split(string(content), "\n")
	currentSection := ""

	for _, line := range lines {
		line = strings.TrimSpace(line)

		// Skip comments and empty lines
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Section header
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			currentSection = strings.Trim(line, "[]")
			continue
		}

		// Key-value pair
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.TrimSpace(parts[0])
		value := strings.TrimSpace(parts[1])

		// Remove quotes
		if (strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"")) ||
			(strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'")) {
			value = value[1 : len(value)-1]
		}

		fullKey := key
		if currentSection != "" {
			fullKey = currentSection + "." + key
		}

		result[fullKey] = parseEnvValue(value)
	}

	return result, nil
}

// merge combines all layers into a final config.
func (l *Loader) merge() (*Config, error) {
	// Start with defaults
	cfg := Default()

	// Apply each layer in priority order
	for layer := LayerGlobal; layer <= LayerCLI; layer++ {
		data, ok := l.layers[layer]
		if !ok || len(data) == 0 {
			continue
		}

		if err := applyLayerToConfig(cfg, data); err != nil {
			return nil, fmt.Errorf("apply layer %s: %w", layer, err)
		}
	}

	return cfg, nil
}

// applyLayerToConfig applies a map of settings to a config struct.
func applyLayerToConfig(cfg *Config, data map[string]any) error {
	for key, value := range data {
		if err := SetConfigField(cfg, key, value); err != nil {
			// Log but don't fail on unknown keys
			continue
		}
	}
	return nil
}

// flattenMap converts nested map values into dot-notation keys.
func flattenMap(data map[string]any) map[string]any {
	out := make(map[string]any)
	var walk func(prefix string, value any)
	walk = func(prefix string, value any) {
		switch v := value.(type) {
		case map[string]any:
			for k, child := range v {
				next := k
				if prefix != "" {
					next = prefix + "." + k
				}
				walk(next, child)
			}
		case map[any]any:
			for k, child := range v {
				key := fmt.Sprintf("%v", k)
				next := key
				if prefix != "" {
					next = prefix + "." + key
				}
				walk(next, child)
			}
		default:
			if prefix != "" {
				out[prefix] = v
			}
		}
	}
	for k, v := range data {
		walk(k, v)
	}
	return out
}

// SetConfigField sets a config field by path (e.g., "security.sandbox").
func SetConfigField(cfg *Config, path string, value any) error {
	parts := strings.Split(path, ".")

	// Handle top-level fields
	if len(parts) == 1 {
		return setTopLevelField(cfg, path, value)
	}

	// Handle nested fields
	switch parts[0] {
	case "security":
		return setSecurityField(&cfg.Security, parts[1], value)
	case "log":
		return setLogField(&cfg.Log, parts[1], value)
	case "lsp":
		return setLSPField(&cfg.LSP, parts[1], value)
	case "notifications":
		return setNotificationField(&cfg.Notifications, parts[1], value)
	case "diagnostics":
		return setDiagnosticsField(&cfg.Diagnostics, parts[1], value)
	case "coordinator":
		return setCoordinatorField(&cfg.Coordinator, parts[1], value)
	}

	return fmt.Errorf("unknown field: %s", path)
}

