// Analyze generates tuning recommendations based on collected metrics.
func (at *AutoTuner) Analyze(cfg *Config) []TuningRecommendation {
	at.mu.RLock()
	defer at.mu.RUnlock()

	var recs []TuningRecommendation

	// Context window tuning
	if rec := at.analyzeContextUsage(cfg); rec != nil {
		recs = append(recs, *rec)
	}

	// File size tuning
	if rec := at.analyzeFileSizes(cfg); rec != nil {
		recs = append(recs, *rec)
	}

	// Tree depth tuning
	if rec := at.analyzeTreeFiles(cfg); rec != nil {
		recs = append(recs, *rec)
	}

	// Provider tuning
	if rec := at.analyzeProviders(cfg); rec != nil {
		recs = append(recs, *rec)
	}

	// Compression tuning
	if rec := at.analyzeCompression(cfg); rec != nil {
		recs = append(recs, *rec)
	}

	// Mode preference
	if rec := at.analyzeModePreference(cfg); rec != nil {
		recs = append(recs, *rec)
	}

	return recs
}

// analyzeContextUsage recommends context token adjustments.
func (at *AutoTuner) analyzeContextUsage(cfg *Config) *TuningRecommendation {
	if len(at.metrics.ContextUsageSamples) < at.minSamples {
		return nil
	}

	avg := average(at.metrics.ContextUsageSamples)
	max := maximum(at.metrics.ContextUsageSamples)

	// If consistently using less than 50% of context, suggest smaller window
	if max < 0.5 && avg < 0.3 {
		suggested := int(float64(cfg.MaxContextTokens) * 0.5)
		return &TuningRecommendation{
			Field:      "maxContextTokens",
			CurrentVal: cfg.MaxContextTokens,
			SuggestVal: suggested,
			Reason:     fmt.Sprintf("Average context usage is %.1f%%, max %.1f%%", avg*100, max*100),
			Impact:     "Reduces memory usage and may improve response times",
			Confidence: 0.8,
			AutoApply:  false,
		}
	}

	// If hitting warnings frequently, suggest larger window
	warningRate := float64(at.metrics.ContextWarnings) / float64(len(at.metrics.ContextUsageSamples))
	if warningRate > 0.2 && avg > 0.7 {
		suggested := int(float64(cfg.MaxContextTokens) * 1.5)
		if suggested > 200000 {
			suggested = 200000
		}
		return &TuningRecommendation{
			Field:      "maxContextTokens",
			CurrentVal: cfg.MaxContextTokens,
			SuggestVal: suggested,
			Reason:     fmt.Sprintf("Context warnings in %.1f%% of sessions", warningRate*100),
			Impact:     "Reduces need for context compression",
			Confidence: 0.7,
			AutoApply:  false,
		}
	}

	return nil
}

// analyzeFileSizes recommends file size limit adjustments.
func (at *AutoTuner) analyzeFileSizes(cfg *Config) *TuningRecommendation {
	if len(at.metrics.FileReadSizes) < at.minSamples {
		return nil
	}

	// Find 95th percentile file size
	sorted := make([]int64, len(at.metrics.FileReadSizes))
	copy(sorted, at.metrics.FileReadSizes)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i] < sorted[j] })
	p95 := sorted[int(float64(len(sorted))*0.95)]

	// If 95th percentile is much smaller than limit, suggest reduction
	if float64(p95) < float64(cfg.MaxAutoReadFileSize)*0.3 {
		suggested := int(float64(p95) * 1.5)
		if suggested < 64*1024 {
			suggested = 64 * 1024 // Min 64KB
		}
		return &TuningRecommendation{
			Field:      "maxAutoReadFileSize",
			CurrentVal: cfg.MaxAutoReadFileSize,
			SuggestVal: suggested,
			Reason:     fmt.Sprintf("95%% of files are smaller than %dKB", p95/1024),
			Impact:     "Faster file processing",
			Confidence: 0.75,
			AutoApply:  true,
		}
	}

	return nil
}

// analyzeTreeFiles recommends tree file limit adjustments.
func (at *AutoTuner) analyzeTreeFiles(cfg *Config) *TuningRecommendation {
	if len(at.metrics.TreeFileCounts) < 5 {
		return nil
	}

	max := 0
	for _, count := range at.metrics.TreeFileCounts {
		if count > max {
			max = count
		}
	}

	// If max is much lower than limit, suggest reduction
	if max < cfg.MaxTreeFiles/2 {
		suggested := max * 2
		if suggested < 100 {
			suggested = 100
		}
		return &TuningRecommendation{
			Field:      "maxTreeFiles",
			CurrentVal: cfg.MaxTreeFiles,
			SuggestVal: suggested,
			Reason:     fmt.Sprintf("Max observed tree size is %d files", max),
			Impact:     "Faster directory scanning",
			Confidence: 0.7,
			AutoApply:  true,
		}
	}

	return nil
}

// analyzeProviders recommends provider changes based on performance.
func (at *AutoTuner) analyzeProviders(cfg *Config) *TuningRecommendation {
	if len(at.metrics.ProviderLatency) < 2 {
		return nil
	}

	// Find provider with best latency/error ratio
	type providerScore struct {
		name       string
		avgLatency time.Duration
		errorRate  float64
		score      float64
	}

	var scores []providerScore
	for provider, latencies := range at.metrics.ProviderLatency {
		if len(latencies) < 5 {
			continue
		}

		avgLatency := averageDuration(latencies)
		errorRate := float64(at.metrics.ProviderErrors[provider]) / float64(at.metrics.ProviderUsage[provider])

		// Score: lower is better (latency in seconds + error penalty)
		score := avgLatency.Seconds() + (errorRate * 5)

		scores = append(scores, providerScore{
			name:       provider,
			avgLatency: avgLatency,
			errorRate:  errorRate,
			score:      score,
		})
	}

	if len(scores) < 2 {
		return nil
	}

	sort.Slice(scores, func(i, j int) bool { return scores[i].score < scores[j].score })
	best := scores[0]
	current := cfg.Provider

	// Only suggest if significantly better (30%+)
	var currentScore *providerScore
	for _, s := range scores {
		if s.name == current {
			currentScore = &s
			break
		}
	}

	if currentScore != nil && best.name != current && best.score < currentScore.score*0.7 {
		return &TuningRecommendation{
			Field:      "provider",
			CurrentVal: current,
			SuggestVal: best.name,
			Reason:     fmt.Sprintf("%s has %.0f%% faster response times", best.name, (1-best.avgLatency.Seconds()/currentScore.avgLatency.Seconds())*100),
			Impact:     "Improved response times",
			Confidence: 0.6,
			AutoApply:  false,
		}
	}

	return nil
}

// analyzeCompression recommends compression threshold adjustments.
func (at *AutoTuner) analyzeCompression(cfg *Config) *TuningRecommendation {
	if at.metrics.CompressionEvents < 5 {
		return nil
	}

	compressionRate := float64(at.metrics.CompressionEvents) / float64(at.metrics.SessionCount)

	// If compressing too often, raise threshold
	if compressionRate > 0.5 && cfg.AutoCompressAt < 0.95 {
		return &TuningRecommendation{
			Field:      "autoCompressAt",
			CurrentVal: cfg.AutoCompressAt,
			SuggestVal: 0.95,
			Reason:     fmt.Sprintf("Compression occurs in %.0f%% of sessions", compressionRate*100),
			Impact:     "Fewer interruptions from compression",
			Confidence: 0.7,
			AutoApply:  true,
		}
	}

	return nil
}

// analyzeModePreference recommends mode based on usage patterns.
func (at *AutoTuner) analyzeModePreference(cfg *Config) *TuningRecommendation {
	if len(at.metrics.ModeUsage) < 2 {
		return nil
	}

	// Find most used mode
	var topMode string
	var topCount int
	var totalCount int

	for mode, count := range at.metrics.ModeUsage {
		totalCount += count
		if count > topCount {
			topCount = count
			topMode = mode
		}
	}

	// If a mode is used 70%+ of the time and it's not the default, suggest it
	if float64(topCount)/float64(totalCount) > 0.7 && topMode != cfg.Mode {
		return &TuningRecommendation{
			Field:      "mode",
			CurrentVal: cfg.Mode,
			SuggestVal: topMode,
			Reason:     fmt.Sprintf("You use %s mode %.0f%% of the time", topMode, float64(topCount)/float64(totalCount)*100),
			Impact:     "Sets your preferred mode as default",
			Confidence: 0.85,
			AutoApply:  false,
		}
	}

	return nil
}

// ApplyRecommendation applies a recommendation to the config.
func (at *AutoTuner) ApplyRecommendation(cfg *Config, rec TuningRecommendation) error {
	at.mu.Lock()
	defer at.mu.Unlock()

	// Apply the change
	if err := SetConfigField(cfg, rec.Field, rec.SuggestVal); err != nil {
		return fmt.Errorf("apply recommendation: %w", err)
	}

	// Record the application
	at.state.AppliedRecommendations = append(at.state.AppliedRecommendations, AppliedRecommendation{
		Recommendation: rec,
		AppliedAt:      time.Now(),
		PreviousValue:  rec.CurrentVal,
		Outcome:        "pending",
	})

	at.state.LastTuneTime = time.Now()
	at.state.Iteration++

	return nil
}

// GetAppliedRecommendations returns history of applied recommendations.
func (at *AutoTuner) GetAppliedRecommendations() []AppliedRecommendation {
	at.mu.RLock()
	defer at.mu.RUnlock()
	return at.state.AppliedRecommendations
}

// OnTune registers a callback for tuning recommendations.
func (at *AutoTuner) OnTune(fn func(TuningRecommendation)) {
	at.mu.Lock()
	defer at.mu.Unlock()
	at.onTune = append(at.onTune, fn)
}

// Reset clears all metrics and state.
func (at *AutoTuner) Reset() error {
	at.mu.Lock()
	defer at.mu.Unlock()

	at.metrics = at.newMetrics()
	at.state = &TuningState{}

	return at.Save()
}

// ExportMetrics exports metrics to a file.
func (at *AutoTuner) ExportMetrics(path string) error {
	at.mu.RLock()
	defer at.mu.RUnlock()

	data, err := yaml.Marshal(at.metrics)
	if err != nil {
		return fmt.Errorf("marshal metrics: %w", err)
	}

	return os.WriteFile(path, data, 0o644)
}

// Utility functions

func average(values []float64) float64 {
	if len(values) == 0 {
		return 0
	}
	var sum float64
	for _, v := range values {
		sum += v
	}
	return sum / float64(len(values))
}

func maximum(values []float64) float64 {
	if len(values) == 0 {
		return 0
	}
	max := values[0]
	for _, v := range values[1:] {
		if v > max {
			max = v
		}
	}
	return max
}

func averageDuration(values []time.Duration) time.Duration {
	if len(values) == 0 {
		return 0
	}
	var sum time.Duration
	for _, v := range values {
		sum += v
	}
	return sum / time.Duration(len(values))
}

// stdDev calculates standard deviation.
func stdDev(values []float64) float64 {
	if len(values) == 0 {
		return 0
	}
	avg := average(values)
	var sumSq float64
	for _, v := range values {
		diff := v - avg
		sumSq += diff * diff
	}
	return math.Sqrt(sumSq / float64(len(values)))
}

package config

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// MigrationVersion represents a config version.
type MigrationVersion struct {
	Major int
	Minor int
	Patch int
}

// String returns the version string.
func (v MigrationVersion) String() string {
	return fmt.Sprintf("%d.%d.%d", v.Major, v.Minor, v.Patch)
}

// Compare returns -1 if v < other, 0 if v == other, 1 if v > other.
func (v MigrationVersion) Compare(other MigrationVersion) int {
	if v.Major != other.Major {
		if v.Major < other.Major {
			return -1
		}
		return 1
	}
	if v.Minor != other.Minor {
		if v.Minor < other.Minor {
			return -1
		}
		return 1
	}
	if v.Patch != other.Patch {
		if v.Patch < other.Patch {
			return -1
		}
		return 1
	}
	return 0
}

// ParseVersion parses a version string.
func ParseVersion(s string) (MigrationVersion, error) {
	s = strings.TrimPrefix(s, "v")
	parts := strings.Split(s, ".")

	v := MigrationVersion{}
	if len(parts) >= 1 {
		v.Major, _ = strconv.Atoi(parts[0])
	}
	if len(parts) >= 2 {
		v.Minor, _ = strconv.Atoi(parts[1])
	}
	if len(parts) >= 3 {
		v.Patch, _ = strconv.Atoi(parts[2])
	}

	return v, nil
}

// CurrentVersion is the current config schema version.
var CurrentVersion = MigrationVersion{Major: 2, Minor: 0, Patch: 0}

// Migration represents a config migration.
type Migration struct {
	FromVersion MigrationVersion
	ToVersion   MigrationVersion
	Description string
	Migrate     func(data map[string]any) (map[string]any, error)
	Rollback    func(data map[string]any) (map[string]any, error)
}

// Migrator handles config migrations.
type Migrator struct {
	migrations []Migration
	backupDir  string
}

// NewMigrator creates a new migrator with all registered migrations.
func NewMigrator() (*Migrator, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("get home dir: %w", err)
	}

	backupDir := filepath.Join(home, ".automergent", "backups")
	if err := os.MkdirAll(backupDir, 0o755); err != nil {
		return nil, fmt.Errorf("create backup dir: %w", err)
	}

	m := &Migrator{
		backupDir: backupDir,
		migrations: []Migration{
			migration_1_0_to_1_1(),
			migration_1_1_to_1_2(),
			migration_1_2_to_2_0(),
		},
	}

	return m, nil
}

// migration_1_0_to_1_1 handles 1.0 -> 1.1 migration.
func migration_1_0_to_1_1() Migration {
	return Migration{
		FromVersion: MigrationVersion{1, 0, 0},
		ToVersion:   MigrationVersion{1, 1, 0},
		Description: "Add diagnostics config section",
		Migrate: func(data map[string]any) (map[string]any, error) {
			if _, ok := data["diagnostics"]; !ok {
				data["diagnostics"] = map[string]any{
					"enabled":          true,
					"showInRead":       true,
					"blockOnError":     true,
					"blockOnWarning":   false,
					"maxFileSizeBytes": 1 << 20,
					"cacheDurationSec": 30,
				}
			}
			return data, nil
		},
		Rollback: func(data map[string]any) (map[string]any, error) {
			delete(data, "diagnostics")
			return data, nil
		},
	}
}

// migration_1_1_to_1_2 handles 1.1 -> 1.2 migration.
func migration_1_1_to_1_2() Migration {
	return Migration{
		FromVersion: MigrationVersion{1, 1, 0},
		ToVersion:   MigrationVersion{1, 2, 0},
		Description: "Rename sandbox modes",
		Migrate: func(data map[string]any) (map[string]any, error) {
			if security, ok := data["security"].(map[string]any); ok {
				if sandbox, ok := security["sandbox"].(string); ok {
					// Rename old values
					switch sandbox {
					case "none":
						security["sandbox"] = "off"
					case "permissive":
						security["sandbox"] = "auto"
					case "full":
						security["sandbox"] = "strict"
					}
				}
			}
			return data, nil
		},
		Rollback: func(data map[string]any) (map[string]any, error) {
			if security, ok := data["security"].(map[string]any); ok {
				if sandbox, ok := security["sandbox"].(string); ok {
					switch sandbox {
					case "off":
						security["sandbox"] = "none"
					case "auto":
						security["sandbox"] = "permissive"
					case "strict":
						security["sandbox"] = "full"
					}
				}
			}
			return data, nil
		},
	}
}

// migration_1_2_to_2_0 handles 1.2 -> 2.0 migration (breaking changes).
func migration_1_2_to_2_0() Migration {
	return Migration{
		FromVersion: MigrationVersion{1, 2, 0},
		ToVersion:   MigrationVersion{2, 0, 0},
		Description: "Major restructuring: flatten provider config, add profiles support",
		Migrate: func(data map[string]any) (map[string]any, error) {
			// Move apiKey from top level to providers
			if apiKey, ok := data["apiKey"].(string); ok {
				provider := "google"
				if p, ok := data["provider"].(string); ok {
					provider = p
				}

				if data["providers"] == nil {
					data["providers"] = make(map[string]any)
				}
				providers := data["providers"].(map[string]any)
				if providers[provider] == nil {
					providers[provider] = make(map[string]any)
				}
				providerConfig := providers[provider].(map[string]any)
				providerConfig["apiKey"] = apiKey
				delete(data, "apiKey")
			}

			// Rename deprecated fields
			if oldField, ok := data["maxTokens"]; ok {
				data["maxContextTokens"] = oldField
				delete(data, "maxTokens")
			}

			// Add version marker
			data["_version"] = "2.0.0"

			return data, nil
		},
		Rollback: func(data map[string]any) (map[string]any, error) {
			// Move apiKey back to top level
			if providers, ok := data["providers"].(map[string]any); ok {
				provider := "google"
				if p, ok := data["provider"].(string); ok {
					provider = p
				}
				if pc, ok := providers[provider].(map[string]any); ok {
					if apiKey, ok := pc["apiKey"].(string); ok {
						data["apiKey"] = apiKey
					}
				}
			}

			// Rename fields back
			if newField, ok := data["maxContextTokens"]; ok {
				data["maxTokens"] = newField
				delete(data, "maxContextTokens")
			}

			delete(data, "_version")

			return data, nil
		},
	}
}

// Migrate migrates a config file to the latest version.
func (m *Migrator) Migrate(path string) error {
	// Read current config
	content, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read config: %w", err)
	}

	var data map[string]any
	if err := yaml.Unmarshal(content, &data); err != nil {
		return fmt.Errorf("parse config: %w", err)
	}

	// Detect version
	currentVersion := m.detectVersion(data)

	// Check if migration needed
	if currentVersion.Compare(CurrentVersion) >= 0 {
		return nil // Already at or above current version
	}

	// Create backup
	if err := m.createBackup(path, content); err != nil {
		return fmt.Errorf("create backup: %w", err)
	}

	// Apply migrations sequentially
	for _, migration := range m.migrations {
		if currentVersion.Compare(migration.FromVersion) >= 0 &&
			currentVersion.Compare(migration.ToVersion) < 0 {

			data, err = migration.Migrate(data)
			if err != nil {
				return fmt.Errorf("migration %s: %w", migration.Description, err)
			}
			currentVersion = migration.ToVersion
		}
	}

	// Write migrated config
	output, err := yaml.Marshal(data)
	if err != nil {
		return fmt.Errorf("marshal config: %w", err)
	}

	if err := os.WriteFile(path, output, 0o644); err != nil {
		return fmt.Errorf("write config: %w", err)
	}

	return nil
}

// detectVersion detects the version of a config.
func (m *Migrator) detectVersion(data map[string]any) MigrationVersion {
	// Check explicit version marker
	if v, ok := data["_version"].(string); ok {
		ver, err := ParseVersion(v)
		if err == nil {
			return ver
		}
	}

	// Heuristic detection based on fields
	if _, ok := data["diagnostics"]; !ok {
		return MigrationVersion{1, 0, 0}
	}

	if security, ok := data["security"].(map[string]any); ok {
		if sandbox, ok := security["sandbox"].(string); ok {
			switch sandbox {
			case "none", "permissive", "full":
				return MigrationVersion{1, 1, 0}
			}
		}
	}

	if _, ok := data["apiKey"]; ok {
		return MigrationVersion{1, 2, 0}
	}

	return CurrentVersion
}

// createBackup creates a backup of the config file.
func (m *Migrator) createBackup(path string, content []byte) error {
	timestamp := time.Now().Format("20060102-150405")
	base := filepath.Base(path)
	backupPath := filepath.Join(m.backupDir, fmt.Sprintf("%s.%s.bak", base, timestamp))

	return os.WriteFile(backupPath, content, 0o644)
}

// ListBackups lists available config backups.
func (m *Migrator) ListBackups() ([]string, error) {
	entries, err := os.ReadDir(m.backupDir)
	if err != nil {
		return nil, err
	}

	var backups []string
	for _, entry := range entries {
		if strings.HasSuffix(entry.Name(), ".bak") {
			backups = append(backups, filepath.Join(m.backupDir, entry.Name()))
		}
	}

	return backups, nil
}

// Restore restores a config from backup.
func (m *Migrator) Restore(backupPath, targetPath string) error {
	content, err := os.ReadFile(backupPath)
	if err != nil {
		return fmt.Errorf("read backup: %w", err)
	}

	return os.WriteFile(targetPath, content, 0o644)
}

// ImportFormat represents a config format to import from.
type ImportFormat string

const (
	ImportClaudeCode ImportFormat = "claude-code"
	ImportCursor     ImportFormat = "cursor"
	ImportCopilot    ImportFormat = "copilot"
	ImportGeneric    ImportFormat = "generic"
)

// Import imports configuration from another tool.
func Import(format ImportFormat, sourcePath string) (*Config, error) {
	content, err := os.ReadFile(sourcePath)
	if err != nil {
		return nil, fmt.Errorf("read source: %w", err)
	}

	cfg := Default()

	switch format {
	case ImportClaudeCode:
		return importClaudeCode(content, cfg)
	case ImportCursor:
		return importCursor(content, cfg)
	case ImportCopilot:
		return importCopilot(content, cfg)
	case ImportGeneric:
		return importGeneric(content, cfg)
	}

	return nil, fmt.Errorf("unknown import format: %s", format)
}

// importClaudeCode imports Claude Code config.
func importClaudeCode(content []byte, cfg *Config) (*Config, error) {
	var data map[string]any

	// Try JSON first (Claude Code uses JSON)
	if err := json.Unmarshal(content, &data); err != nil {
		// Try YAML
		if err := yaml.Unmarshal(content, &data); err != nil {
			return nil, fmt.Errorf("parse config: %w", err)
		}
	}

	// Map Claude Code fields to Automergent
	if model, ok := data["model"].(string); ok {
		cfg.Model = model
	}

	if theme, ok := data["theme"].(string); ok {
		cfg.Theme = theme
	}

	// Map Claude Code's allowed_tools to Automergent's tools config
	if allowedTools, ok := data["allowed_tools"].([]any); ok {
		for _, t := range allowedTools {
			if tool, ok := t.(string); ok {
				cfg.Tools[tool] = ToolConfig{Enabled: true}
			}
		}
	}

	// Map Claude Code's environment config
	if env, ok := data["environment"].(map[string]any); ok {
		if timeout, ok := env["command_timeout"].(string); ok {
			cfg.Tools["shell"] = ToolConfig{
				Enabled: true,
				Timeout: timeout,
			}
		}
	}

	// Map MCP servers
	if mcpServers, ok := data["mcpServers"].(map[string]any); ok {
		for name, serverData := range mcpServers {
			if server, ok := serverData.(map[string]any); ok {
				mcpServer := MCPServer{}
				if cmd, ok := server["command"].(string); ok {
					mcpServer.Command = []string{cmd}
				}
				if args, ok := server["args"].([]any); ok {
					for _, arg := range args {
						if a, ok := arg.(string); ok {
							mcpServer.Command = append(mcpServer.Command, a)
						}
					}
				}
				cfg.MCP.Servers[name] = mcpServer
			}
		}
	}

	return cfg, nil
}

// importCursor imports Cursor IDE config.
func importCursor(content []byte, cfg *Config) (*Config, error) {
	var data map[string]any
	if err := json.Unmarshal(content, &data); err != nil {
		return nil, fmt.Errorf("parse config: %w", err)
	}

	// Map Cursor AI settings
	if ai, ok := data["ai"].(map[string]any); ok {
		if model, ok := ai["model"].(string); ok {
			cfg.Model = model
		}
		if provider, ok := ai["provider"].(string); ok {
			cfg.Provider = strings.ToLower(provider)
		}
	}

	// Map editor settings
	if editor, ok := data["editor"].(map[string]any); ok {
		if theme, ok := editor["theme"].(string); ok {
			cfg.Theme = mapTheme(theme)
		}
	}

	return cfg, nil
}

// importCopilot imports GitHub Copilot config.
func importCopilot(content []byte, cfg *Config) (*Config, error) {
	var data map[string]any
	if err := json.Unmarshal(content, &data); err != nil {
		return nil, fmt.Errorf("parse config: %w", err)
	}

	// Map Copilot settings
	cfg.Provider = "google"

	if advanced, ok := data["advanced"].(map[string]any); ok {
		if debug, ok := advanced["debug"].(bool); ok && debug {
			cfg.Verbose = true
		}
	}

	return cfg, nil
}

// importGeneric imports a generic YAML/JSON config.
func importGeneric(content []byte, cfg *Config) (*Config, error) {
	var data map[string]any

	// Try JSON first
	if err := json.Unmarshal(content, &data); err != nil {
		// Try YAML
		if err := yaml.Unmarshal(content, &data); err != nil {
			return nil, fmt.Errorf("parse config: %w", err)
		}
	}

	// Direct field mapping
	directFields := []string{
		"provider", "model", "mode", "theme", "keybindings", "layout",
		"autoSave", "maxSessions", "verbose", "quiet", "noColor",
	}

	for _, field := range directFields {
		if value, ok := data[field]; ok {
			_ = SetConfigField(cfg, field, value)
		}
	}

	return cfg, nil
}

// mapTheme maps external themes to Automergent themes.
func mapTheme(external string) string {
	themeMap := map[string]string{
		"Dracula":      "dracula",
		"One Dark":     "onedark",
		"One Dark Pro": "onedark",
		"Nord":         "nord",
		"Gruvbox":      "gruvbox",
		"Gruvbox Dark": "gruvbox",
		"Monokai":      "monokai",
		"Monokai Pro":  "monokai",
		"Catppuccin":   "catppuccin",
		"Default":      "default",
	}

	if mapped, ok := themeMap[external]; ok {
		return mapped
	}

	// Try case-insensitive match
	lower := strings.ToLower(external)
	for ext, internal := range themeMap {
		if strings.ToLower(ext) == lower {
			return internal
		}
	}

	return "default"
}

// Export exports the current config.
func Export(cfg *Config, path string) error {
	ext := strings.ToLower(filepath.Ext(path))

	var data []byte
	var err error

	switch ext {
	case ".json":
		data, err = json.MarshalIndent(cfg, "", "  ")
	case ".yaml", ".yml":
		data, err = yaml.Marshal(cfg)
	default:
		data, err = yaml.Marshal(cfg)
	}

	if err != nil {
		return fmt.Errorf("marshal config: %w", err)
	}

	return os.WriteFile(path, data, 0o644)
}

// DetectImportFormat attempts to detect the format of a config file.
func DetectImportFormat(path string) ImportFormat {
	content, err := os.ReadFile(path)
	if err != nil {
		return ImportGeneric
	}

	// Check for Claude Code markers
	if matched, _ := regexp.Match(`"allowed_tools"`, content); matched {
		return ImportClaudeCode
	}
	if matched, _ := regexp.Match(`"mcpServers"`, content); matched {
		return ImportClaudeCode
	}

	// Check for Cursor markers
	if matched, _ := regexp.Match(`"cursor\."`, content); matched {
		return ImportCursor
	}

	// Check for Copilot markers
	if matched, _ := regexp.Match(`"github\.copilot"`, content); matched {
		return ImportCopilot
	}

	return ImportGeneric
}

package config

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// Profile represents a named configuration profile.
type Profile struct {
	// Name is the profile identifier.
	Name string `yaml:"name" json:"name"`
	// Description explains the profile's purpose.
	Description string `yaml:"description,omitempty" json:"description,omitempty"`
	// Inherits specifies parent profile(s) to inherit from.
	Inherits []string `yaml:"inherits,omitempty" json:"inherits,omitempty"`
	// Environment specifies when this profile should auto-activate.
	Environment string `yaml:"environment,omitempty" json:"environment,omitempty"`
	// Config holds the profile-specific configuration overrides.
	Config map[string]any `yaml:"config" json:"config"`
	// Metadata holds additional profile information.
	Metadata ProfileMetadata `yaml:"metadata,omitempty" json:"metadata,omitempty"`
}

// ProfileMetadata holds profile metadata.
type ProfileMetadata struct {
	// Author is the profile creator.
	Author string `yaml:"author,omitempty" json:"author,omitempty"`
	// Version is the profile version.
	Version string `yaml:"version,omitempty" json:"version,omitempty"`
	// Created is when the profile was created.
	Created string `yaml:"created,omitempty" json:"created,omitempty"`
	// Tags are searchable tags.
	Tags []string `yaml:"tags,omitempty" json:"tags,omitempty"`
}

// ProfileManager handles profile operations.
type ProfileManager struct {
	profilesDir string
	profiles    map[string]*Profile
}

// NewProfileManager creates a new profile manager.
func NewProfileManager() (*ProfileManager, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("get home dir: %w", err)
	}

	profilesDir := filepath.Join(home, ".automergent", "profiles")
	if err := os.MkdirAll(profilesDir, 0o755); err != nil {
		return nil, fmt.Errorf("create profiles dir: %w", err)
	}

	pm := &ProfileManager{
		profilesDir: profilesDir,
		profiles:    make(map[string]*Profile),
	}

	// Load existing profiles
	if err := pm.loadProfiles(); err != nil {
		return nil, err
	}

	return pm, nil
}

// loadProfiles loads all profiles from disk.
func (pm *ProfileManager) loadProfiles() error {
	entries, err := os.ReadDir(pm.profilesDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}

		ext := filepath.Ext(entry.Name())
		if ext != ".yaml" && ext != ".yml" && ext != ".json" {
			continue
		}

		path := filepath.Join(pm.profilesDir, entry.Name())
		profile, err := pm.loadProfile(path)
		if err != nil {
			continue // Skip invalid profiles
		}

		pm.profiles[profile.Name] = profile
	}

	return nil
}

// loadProfile loads a single profile from a file.
func (pm *ProfileManager) loadProfile(path string) (*Profile, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	var profile Profile
	if err := yaml.Unmarshal(content, &profile); err != nil {
		return nil, fmt.Errorf("parse profile: %w", err)
	}

	// Use filename as name if not specified
	if profile.Name == "" {
		base := filepath.Base(path)
		profile.Name = strings.TrimSuffix(base, filepath.Ext(base))
	}

	return &profile, nil
}

// Get returns a profile by name.
func (pm *ProfileManager) Get(name string) (*Profile, error) {
	profile, ok := pm.profiles[name]
	if !ok {
		return nil, fmt.Errorf("profile %q not found", name)
	}
	return profile, nil
}

// List returns all available profiles.
func (pm *ProfileManager) List() []*Profile {
	profiles := make([]*Profile, 0, len(pm.profiles))
	for _, p := range pm.profiles {
		profiles = append(profiles, p)
	}
	sort.Slice(profiles, func(i, j int) bool {
		return profiles[i].Name < profiles[j].Name
	})
	return profiles
}

// ListNames returns all profile names.
func (pm *ProfileManager) ListNames() []string {
	names := make([]string, 0, len(pm.profiles))
	for name := range pm.profiles {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Create creates a new profile.
func (pm *ProfileManager) Create(profile *Profile) error {
	if profile.Name == "" {
		return fmt.Errorf("profile name is required")
	}

	if _, exists := pm.profiles[profile.Name]; exists {
		return fmt.Errorf("profile %q already exists", profile.Name)
	}

	// Validate inheritance
	for _, parent := range profile.Inherits {
		if _, ok := pm.profiles[parent]; !ok {
			return fmt.Errorf("parent profile %q not found", parent)
		}
	}

	// Save to disk
	if err := pm.saveProfile(profile); err != nil {
		return err
	}

	pm.profiles[profile.Name] = profile
	return nil
}

// Update updates an existing profile.
func (pm *ProfileManager) Update(profile *Profile) error {
	if _, exists := pm.profiles[profile.Name]; !exists {
		return fmt.Errorf("profile %q not found", profile.Name)
	}

	if err := pm.saveProfile(profile); err != nil {
		return err
	}

	pm.profiles[profile.Name] = profile
	return nil
}

// Delete removes a profile.
func (pm *ProfileManager) Delete(name string) error {
	if _, exists := pm.profiles[name]; !exists {
		return fmt.Errorf("profile %q not found", name)
	}

	path := filepath.Join(pm.profilesDir, name+".yaml")
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("delete profile file: %w", err)
	}

	delete(pm.profiles, name)
	return nil
}

// saveProfile saves a profile to disk.
func (pm *ProfileManager) saveProfile(profile *Profile) error {
	path := filepath.Join(pm.profilesDir, profile.Name+".yaml")

	data, err := yaml.Marshal(profile)
	if err != nil {
		return fmt.Errorf("marshal profile: %w", err)
	}

	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write profile: %w", err)
	}

	return nil
}

// Resolve resolves a profile with inheritance.
func (pm *ProfileManager) Resolve(name string) (map[string]any, error) {
	profile, err := pm.Get(name)
	if err != nil {
		return nil, err
	}

	return pm.resolveWithVisited(profile, make(map[string]bool))
}

// resolveWithVisited resolves inheritance while detecting cycles.
func (pm *ProfileManager) resolveWithVisited(profile *Profile, visited map[string]bool) (map[string]any, error) {
	if visited[profile.Name] {
		return nil, fmt.Errorf("circular inheritance detected: %s", profile.Name)
	}
	visited[profile.Name] = true

	result := make(map[string]any)

	// First, resolve parent profiles
	for _, parentName := range profile.Inherits {
		parent, err := pm.Get(parentName)
		if err != nil {
			return nil, fmt.Errorf("parent %q: %w", parentName, err)
		}

		parentConfig, err := pm.resolveWithVisited(parent, visited)
		if err != nil {
			return nil, err
		}

		// Merge parent config
		for k, v := range parentConfig {
			result[k] = v
		}
	}

	// Then apply this profile's config (overrides parents)
	for k, v := range profile.Config {
		result[k] = v
	}

	return result, nil
}

// Clone creates a copy of an existing profile.
func (pm *ProfileManager) Clone(sourceName, newName string) (*Profile, error) {
	source, err := pm.Get(sourceName)
	if err != nil {
		return nil, err
	}

	if _, exists := pm.profiles[newName]; exists {
		return nil, fmt.Errorf("profile %q already exists", newName)
	}

	newProfile := &Profile{
		Name:        newName,
		Description: fmt.Sprintf("Clone of %s", sourceName),
		Inherits:    append([]string{}, source.Inherits...),
		Environment: source.Environment,
		Config:      make(map[string]any),
		Metadata:    source.Metadata,
	}

	for k, v := range source.Config {
		newProfile.Config[k] = v
	}

	if err := pm.Create(newProfile); err != nil {
		return nil, err
	}

	return newProfile, nil
}

// Export exports a profile to a file.
func (pm *ProfileManager) Export(name, path string) error {
	profile, err := pm.Get(name)
	if err != nil {
		return err
	}

	data, err := yaml.Marshal(profile)
	if err != nil {
		return fmt.Errorf("marshal profile: %w", err)
	}

	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write file: %w", err)
	}

	return nil
}

// Import imports a profile from a file.
func (pm *ProfileManager) Import(path string) (*Profile, error) {
	profile, err := pm.loadProfile(path)
	if err != nil {
		return nil, err
	}

	if err := pm.Create(profile); err != nil {
		return nil, err
	}

	return profile, nil
}

// DetectEnvironment returns the appropriate profile for the current environment.
func (pm *ProfileManager) DetectEnvironment() (*Profile, error) {
	// Check for environment indicator
	env := os.Getenv("AUTOMERGENT_ENV")
	if env == "" {
		env = os.Getenv("GO_ENV")
	}
	if env == "" {
		env = os.Getenv("APP_ENV")
	}
	if env == "" {
		env = os.Getenv("NODE_ENV")
	}

	// Try to find matching profile
	for _, profile := range pm.profiles {
		if profile.Environment == env {
			return profile, nil
		}
	}

	// Try common environment names
	commonEnvs := []string{"development", "dev", "production", "prod", "staging", "test"}
	for _, e := range commonEnvs {
		if strings.Contains(strings.ToLower(env), e) {
			if profile, ok := pm.profiles[e]; ok {
				return profile, nil
			}
		}
	}

	return nil, nil
}

